for (const [variantId, variant] of Object.entries(graphicsOptimizationVariants)) {
  const baseFiles = projectFilesById[variant.baseId] || [];
  projectFilesById[variantId] = baseFiles.map((file) => variant.replacements[file.path]
    ? { ...file, base64: variant.replacements[file.path] }
    : file);
}
